  renameFn?: (
    oldPath: string,
    newPath: string,
  ) => Promise<void>;
}

export type CompactSessionReason =
  | "missing_events_file"
  | "empty_events_file"
  | "already_compacted"
  | "compacted"
  | "would_compact";

