1542	/**
1543	 * Build canonical close_reason for stale auto-abandon updates.
1544	 *
1545	 * Canonical format:
1546	 * auto-abandoned:older-than=<duration>,inactive-for=<duration>,liveness-guard=<duration>,last-activity=<iso>
1547	 */
1548	export function buildAutoAbandonedCloseReason(
1549	  criteria: StaleSessionCriteria,
1550	  evaluation: Pick<StaleSessionEvaluation, "lastActivityAt">,
1551	): string {
1552	  const segments = [
1553	    `older-than=${criteria.olderThan}`,
1554	    `inactive-for=${criteria.inactiveFor}`,
1555	    `liveness-guard=${criteria.livenessGuard}`,
1556	    `last-activity=${evaluation.lastActivityAt}`,
1557	  ];
1558	  return `auto-abandoned:${segments.join(",")}`;
1559	}
1560	
1561	/**
1562	 * Apply abandoned metadata to stale session candidates.
1563	 *
1564	 * All updates in a single invocation share one ended_at timestamp, which lets
1565	 * the caller persist and commit the batch atomically.
1566	 */
1567	export async function applyAutoAbandonMetadata(
1568	  sessionsDir: string,
1569	  selection: Pick<StaleSessionCandidateSelection, "criteria" | "candidates">,
1570	  options?: { dryRun?: boolean; nowMs?: number },
1571	): Promise<AutoAbandonMetadataResult> {
1572	  const dryRun = options?.dryRun === true;
1573	  const endedAt = new Date(options?.nowMs ?? Date.now()).toISOString();
1574	  const updates: AutoAbandonMetadataPreview[] = [];
1575	
1576	  for (const candidate of selection.candidates) {
1577	    const closeReason = buildAutoAbandonedCloseReason(
1578	      selection.criteria,
1579	      candidate,
1580	    );
1581	    updates.push({
1582	      sessionId: candidate.sessionId,
1583	      status: "abandoned",
1584	      endedAt,
1585	      closeReason,
1586	    });
1587	
1588	    if (dryRun) continue;
1589	
1590	    const metadata = await getSession(sessionsDir, candidate.sessionId);
1591	    if (!metadata) continue;
1592	
1593	    const updated: SessionMetadata = {
1594	      ...metadata,
1595	      status: "abandoned",
1596	      ended_at: endedAt,
1597	      close_reason: closeReason,
1598	    };
1599	
1600	    const metadataPath = getSessionMetadataPath(sessionsDir, candidate.sessionId);
1601	    const content = YAML.stringify(updated, {
1602	      indent: 2,
1603	      lineWidth: 100,
1604	      sortMapEntries: false,
1605	    });
1606	    await fsPromises.writeFile(metadataPath, content, "utf-8");
1607	  }
1608	
1609	  return {
1610	    dryRun,
1611	    updatedCount: updates.length,
1612	    updates,
1613	  };
1614	}
1615

